def decimal_to_binary(n):
    """Converts a non-negative integer to its binary representation wrapped with 'db' prefix and suffix.
    Returns the string in format 'db<binary>db'. Raises TypeError for non-integer input and ValueError for negative integers."""
    if type(n) is not int:
        raise TypeError("Input must be an integer")
    if n < 0:
        raise ValueError("Input must be non-negative")
    binary_str = bin(n)[2:]
    return f"db{binary_str}db"

